CREATE TRIGGER [dbo].[ResponsibilityTypeRelationOverrideItem_AfterUpsert] ON [dbo].[ResponsibilityTypeRelationOverrideItem] AFTER INSERT, UPDATE AS BEGIN SET NOCOUNT ON;
update T set T.Overridden = 1, T.OverrideID = S.ID from ResponsibilityTypeRelationRuleResult T inner join inserted S on S.AssetID = T.AssetID and S.ResponsibilityTypeID = T.ResponsibilityTypeID and T.RuleID <> 0;
merge ResponsibilityTypeRelationRuleResult as T using ( select 0 as RuleID, I.ID, I.ResponsibilityTypeID, A.ID as AssetID, A.Object, A.ObjectID, A.AssetTypeID, T.Object as Type, T.ObjectID as TypeID, I.SecurityAsset, I.SecurityAssetID, R.PermissionsBitMask, I.Context from Asset A inner join AssetType T on T.ID = A.AssetTypeID inner join ResponsibilityTypeRelation R on R.ObjectType = T.Object and R.ObjectID = T.ObjectID inner join inserted I on I.AssetID = A.ID and I.ResponsibilityTypeID = R.ResponsibilityTypeID ) as S on ( S.RuleID = T.RuleID and S.ID = T.OverrideID ) when matched then update set T.SecurityAsset = S.SecurityAsset, T.SecurityAssetID = S.SecurityAssetID, T.PermissionsBitMask = S.PermissionsBitMask, T.Context = S.Context, T.ResponsibilityTypeID = S.ResponsibilityTypeID when not matched by target then insert (RuleID, ResponsibilityTypeID, AssetID, AssetTypeID, SecurityAsset, SecurityAssetID, PermissionsBitMask, Context, ApplyToType, IsVisible, Overridden, OverrideID) values (S.RuleID, S.ResponsibilityTypeID, S.AssetID, S.AssetTypeID, S.SecurityAsset, S.SecurityAssetID, S.PermissionsBitMask, S.Context, 0, 1, 0, S.ID); END
ALTER TABLE [dbo].[ResponsibilityTypeRelationOverrideItem] ENABLE TRIGGER [ResponsibilityTypeRelationOverrideItem_AfterUpsert]

CREATE TRIGGER [dbo].[ResponsibilityTypeRelationOverrideItem_AfterDelete] ON [dbo].[ResponsibilityTypeRelationOverrideItem] AFTER DELETE AS BEGIN SET NOCOUNT ON;
delete T from ResponsibilityTypeRelationRuleResult T inner join deleted S on T.RuleID = 0 and T.OverrideID = S.ID;
update T set T.Overridden = 0, T.OverrideID = 0 from ResponsibilityTypeRelationRuleResult T inner join deleted S on T.RuleID <> 0 and T.OverrideID = S.ID; END GO
ALTER TABLE [dbo].[ResponsibilityTypeRelationOverrideItem] ENABLE TRIGGER [ResponsibilityTypeRelationOverrideItem_AfterDelete] GO
